const domains = ["datacolab.pt", "carlosdomingues.pt"]; // <-- ajustar lista de domínios

const config = {
  ssllabs_email: "carlos.domingues@datacolab.pt", // <-- email já registado na API v4 do SSL Labs
  script_path: "/opt/scripts/ssllabs_cert_report.py" // <-- caminho do script no host remoto
};

return domains.map(domain => ({
  json: { domain, ...config }
}));

const item = $input.item.json;
const domain = $('Configuracao de Dominios').item.json.domain;

let resultado;
try {
  resultado = JSON.parse(item.stdout);
} catch (e) {
  resultado = null;
}

const dadosParaAnalise = resultado ?? {
  erro: "Não foi possível interpretar a saída do script.",
  raw: item.stdout,
  stderr: item.stderr || ""
};

const prompt = `Es um analista de cibersegurança sénior. Analisa o relatório técnico seguinte (JSON), produzido pelo script ssllabs_cert_report.py, sobre o(s) certificado(s) TLS do domínio "${domain}".

Regras de decisão:
- days_to_expiry <= 15 (ou negativo, já expirado) => ação necessária (renovar certificado).
- days_to_expiry entre 16 e 30 => sinalizar atenção, mas não é obrigatoriamente ação imediata.
- worst_grade igual a C, D, E, F, "T" (sem confiança na cadeia) ou "M" (mismatch) => ação necessária.
- matches_host = false no certificado relevante para o domínio pedido => ação necessária (certificado errado ou configuração incorreta).
- Se o campo "erro" estiver presente nos dados, é sempre necessária ação de verificação manual.
- Em qualquer outro caso => sem ação necessária.

Responde APENAS com JSON válido, sem comentários nem texto fora do JSON, exatamente neste formato:
{"domain": "...", "deve_agir": true ou false, "urgencia": "baixa" ou "media" ou "alta", "motivo": "frase curta", "acao_recomendada": "frase curta ou null se deve_agir for false"}

Dados do relatório:
${JSON.stringify(dadosParaAnalise)}`;

return {
  json: {
    domain: domain,
    resultado: dadosParaAnalise,
    prompt
  }
};

const domain = $('Preparar Analise').item.json.domain;
const item = $input.item.json;

let decisao;
try {
  // O endpoint /api/generate do Ollama devolve o texto gerado no campo "response"
  decisao = JSON.parse(item.response);
} catch (e) {
  decisao = {
    deve_agir: true,
    urgencia: "media",
    motivo: "Não foi possível interpretar a resposta da IA de forma automática — validar manualmente.",
    acao_recomendada: "Rever manualmente o relatório do domínio."
  };
}

decisao.domain = domain;
return { json: decisao };

const items = $input.all().map(i => i.json);

const linhas = items.map(d => {
  const tag = d.deve_agir ? "\u{1F534} A\u00c7\u00c3O NECESS\u00c1RIA" : "\u{1F7E2} SEM A\u00c7\u00c3O";
  let linha = `${tag} \u2014 ${d.domain}\n  Urg\u00eancia: ${d.urgencia || 'n/d'}\n  Motivo: ${d.motivo || 'n/d'}`;
  if (d.deve_agir && d.acao_recomendada) {
    linha += `\n  A\u00e7\u00e3o recomendada: ${d.acao_recomendada}`;
  }
  return linha;
});

const algumaAcao = items.some(d => d.deve_agir);

return {
  json: {
    resumo: linhas.join("\n\n"),
    algumaAcaoNecessaria: algumaAcao,
    total_dominios: items.length,
    dominios_com_acao: items.filter(d => d.deve_agir).map(d => d.domain)
  }
};
